  await writeFile(inputFile, JSON.stringify(input));
  const child = fork('./src/runner.mjs', [command, inputFile, root, sink], {
    execArgv: [], silent: true,
    env: { ...process.env, PAUSE_AT_RECEIPT: pause ? '1' : '0' }
  });
  children.add(child);
  let output = '', error = '';
  child.stdout.on('data', part => { output += part; });
  child.stderr.on('data', part => { error += part; });
  const done = once(child, 'close', { signal: AbortSignal.timeout(10000) }).then(([code, signal]) => {
